# Product and order filters

This browser application uses native ES modules. `ui.mjs` contains the project's
labelled controls and buttons, and `query.mjs` provides the existing asynchronous
data access. Use the same public controls, data and URLs.

Products have keyword, category and publication status. Users edit a draft and
press Apply. Reset restores published/all categories/empty keyword. Orders have
keyword, date range and order status; a valid edit takes effect immediately.
Reset restores all statuses and the 30 calendar days ending on the project date
from `data.mjs`. Product and order status values describe different concepts.

The URL is the applied filter source. Keep unrelated parameters. Refresh and
browser history restore the appropriate applied fields. Product draft changes
must not start a query. Incomplete or reversed order dates remain editable and
show an associated error without changing the applied URL or results. Query
failures use a visible alert, and earlier responses cannot replace the current
result. Result counts describe the actual returned rows.

Keep the existing control labels, page links and Results list. Narrow containers,
long translated labels, keyboard operation and 200% text sizing must remain
usable without horizontal page overflow. Existing design-system functions in
ui.mjs may be extended while preserving their public behavior. There is no
animation or performance-optimization requirement. Run npm run check.
import { node, field, input, button } from './ui.mjs';
import { products } from './data.mjs';
const app=document.querySelector('#app');
const nav=node('nav');
for(const [name,page] of [['Products','products'],['Orders','orders']]){const a=node('a',name);a.href='/?page='+page;nav.append(a);}
const heading=node('h1','Products');
const form=node('form');form.append(field('Product keyword',input()),button('Apply',e=>e.preventDefault()),button('Reset'));
const count=node('p',products.length+' results');count.setAttribute('role','status');
const list=node('ul');list.setAttribute('aria-label','Results');for(const row of products)list.append(node('li',row.name));
app.append(nav,heading,form,count,list);
export function node(tag, text) { const el=document.createElement(tag); if(text!==undefined)el.textContent=text; return el; }
export function input(type='text') { const el=node('input'); el.type=type; return el; }
export function select(options) { const el=node('select'); for(const [value,label] of options){const option=node('option',label);option.value=value;el.append(option);}return el; }
export function field(label, control) { const el=node('label'); const text=node('span',label);el.append(text,control);return el; }
export function button(label, action, type='button') { const el=node('button',label);el.type=type;if(action)el.addEventListener('click',action);return el; }
import { products, orders } from './data.mjs';
function wait(rows, query) {
 return new Promise((resolve,reject)=>setTimeout(()=>query.q==='error'?reject(Error('Query unavailable')):resolve({rows,count:rows.length}),query.q==='Cap'?250:15));
}
export function queryProducts(f) {return wait(products.filter(row=>(!f.q||row.name.toLowerCase().includes(f.q.toLowerCase()))&&(!f.category||row.category===f.category)&&(!f.status||row.status===f.status)),f);}
export function queryOrders(f) {return wait(orders.filter(row=>(!f.q||row.name.toLowerCase().includes(f.q.toLowerCase()))&&(!f.status||row.status===f.status)&&row.date>=f.from&&row.date<=f.to),f);}
export const today = '2026-10-19';
export const products = [
 {id:'p1',name:'Cap',category:'wear',status:'published'},
 {id:'p2',name:'Tea',category:'food',status:'published'},
 {id:'p3',name:'Mug',category:'home',status:'draft'},
 {id:'p4',name:'Coat',category:'wear',status:'published'},
];
export const orders = [
 {id:'o1',name:'Alice paid',status:'paid',date:'2026-10-15'},
 {id:'o2',name:'Bob new',status:'new',date:'2026-10-17'},
 {id:'o3',name:'Alice new',status:'new',date:'2026-10-01'},
];
