+:root {
+  font: 16px/1.5 system-ui, sans-serif;
+  color: #17212b;
+  background: #f5f7fa;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+body {
+  margin: 0;
+  overflow-wrap: anywhere;
+}
+
+main {
+  width: min(100%, 64rem);
+  margin: auto;
+  padding: 1rem;
+}
+
+nav {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .5rem 1rem;
+}
+
+nav a[aria-current="page"] {
+  font-weight: 700;
+}
+
+.filters {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(min(12rem, 100%), 1fr));
+  align-items: end;
+  gap: 1rem;
+  padding: 1rem;
+  border: 1px solid #d9e0e8;
+  border-radius: .5rem;
+  background: white;
+}
+
+label {
+  display: grid;
+  min-width: 0;
+  gap: .25rem;
+  font-weight: 600;
+}
+
+input,
+select,
+button {
+  min-width: 0;
+  max-width: 100%;
+  padding: .5rem;
+  border: 1px solid #7c8794;
+  border-radius: .25rem;
+  font: inherit;
+}
+
+button {
+  background: #fff;
+  cursor: pointer;
+}
+
+button[type="submit"] {
+  border-color: #1266be;
+  color: #fff;
+  background: #1266be;
+}
+
+.filter-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .5rem;
+}
+
+.field-error,
+.query-error {
+  color: #a11212;
+  font-weight: 600;
+}
+
+.field-error {
+  grid-column: 1 / -1;
+  margin: 0;
+}
+
+.results {
+  margin-top: 1.25rem;
+}
+
+.result-count {
+  font-weight: 700;
+}
+
+li {
+  padding: .4rem;
+}
+
+button:focus-visible,
+input:focus-visible,
+select:focus-visible,
+a:focus-visible {
+  outline: 3px solid #1266be;
+  outline-offset: 2px;
+}
+
+@media (max-width: 24rem) {
+  main {
+    padding: .75rem;
+  }
+
+  .filters {
+    padding: .75rem;
+  }
+}

